package org.opentaint.dataflow.bidi

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.fixtures.MethodAnalysisFixtures
import org.opentaint.dataflow.bidi.interp.starEdge
import org.opentaint.dataflow.bidi.store.DemandStore
import kotlin.test.*

/** Proposal model: apply current AP/C2/C5 operations with a caller-selected collector budget. */
class PremiseRelativeCapProbeTest {
    private val arg=AccessPathBase.Argument(0)
    private val ret=AccessPathBase.Return
    private val tmp=AccessPathBase.LocalVar(0)
    private val objectResult=AccessPathBase.LocalVar(1)
    private data class Result(val initial:AdmittedInitial,val facts:Facts,val cap:Int,val steps:List<String>)

    private fun cap(original:PremiseKey,global:Int,relative:Boolean):Int = when {
        !relative || original.isZero -> global
        else -> minOf(global,(0 until original.size).maxOf { original.member(it).pathArray.count(Int::isCounted) }+1)
    }
    private fun bounded(f:MethodAnalysisFixtures,original:PremiseKey,facts:Facts,global:Int,relative:Boolean):Facts {
        val out=CollectingOut();f.ops.limit(facts,cap(original,global,relative),out)
        return out.results.single()
    }
    private fun fact(f:MethodAnalysisFixtures,value:Facts):String {
        val p=f.ops.leaves(value).single()
        val path=p.fact.path.joinToString(".") { if(it==f.field("a")) "a" else if(it==f.field("b")) "b" else "?" }
        return "${p.fact.base}:$path/${p.fact.tail}/${value.layer}"
    }
    private fun run(f:MethodAnalysisFixtures,seed:AdmittedInitial,edges:List<PathEdge>,global:Int,
                    direction:Direction,relative:Boolean):Result {
        val mode=ApMode(false,direction,global,MarkMode.FULL)
        var current=f.ops.startFact(seed.initial,mode)
        current=current.withLayer(current.layer or(seed.layer==Layer.DEMAND))
        val trace=arrayListOf(fact(f,current))
        for(edge in edges) {
            val out=CollectingOut()
            f.ops.applyEdge(current,seed.initial,edge,statementEdge=true,mode=mode,out=out)
            current=bounded(f,seed.initial,out.results.single(),global,relative)
            trace+=fact(f,current)
        }
        return Result(seed,current,cap(seed.initial,global,relative),trace)
    }
    private fun bind(f:MethodAnalysisFixtures,original:PremiseKey,value:Facts,to:AccessPathBase,global:Int,relative:Boolean):Facts {
        val out=CollectingOut()
        f.ops.applyEdge(value,original,starEdge(value.base,emptyList(),to,emptyList()),false,
            ApMode(false,Direction.FORWARD,global),out)
        return bounded(f,original,out.results.single(),global,relative)
    }
    private fun guide(f:MethodAnalysisFixtures,entry:Pattern,exit:Pattern)=DemandStore.Builder(f.manager).apply {
        add(f.key,DemandPattern(entry,exit))
    }.build()

    @Test fun `separated writer and reader retain the same DEMAND middle at every global budget`() {
        MethodAnalysisFixtures().use { f ->
            val t=MarkSlot.Concrete(f.mark("T"));val a=f.field("a");val b=f.field("b")
            val make=listOf(starEdge(arg,emptyList(),tmp,listOf(b)),
                starEdge(tmp,emptyList(),objectResult,listOf(a)),starEdge(objectResult,emptyList(),ret,emptyList()))
            val take=listOf(starEdge(arg,listOf(a),tmp,emptyList()),starEdge(tmp,listOf(b),ret,emptyList()))
            val sourceActual=f.fact(arg,mark=t)
            val sinkActual=f.fact(ret,mark=t)
            val p=f.manager.initial(f.pattern(arg,mark=t));val r=f.manager.initial(f.pattern(ret,mark=t))
            val writerSeed=AdmittedInitial(p,Layer.NORMAL);val readerSeed=AdmittedInitial(r,Layer.NORMAL)
            var oldRelativeFingerprint:String?=null
            for(global in 1..7) for(relative in listOf(false,true)) {
                val writer=run(f,writerSeed,make,global,Direction.FORWARD,relative)
                val reader=run(f,readerSeed,take.asReversed().map { revEdge(it)!! },global,Direction.BACKWARD,relative)
                val fwPolicy=RestrictedInitialPolicy(run=3,fieldLimit=global,direction=Direction.FORWARD,catalog=f.manager.marks)
                val bwPolicy=RestrictedInitialPolicy(run=4,fieldLimit=global,direction=Direction.BACKWARD,catalog=f.manager.marks)
                val takeGuide=guide(f,f.ops.leaves(reader.facts).single(),r.toPattern())
                val takeInput=bind(f,f.manager.zero,writer.facts,arg,global,relative)
                val takeInitial=takeGuide.initials(f.key,takeInput,fwPolicy).single()
                val takeForward=run(f,takeInitial,take,global,Direction.FORWARD,relative)
                val takeSelected=takeGuide.intersect(f.key,takeInitial.initial,takeForward.facts,fwPolicy).single()
                val makeGuide=guide(f,f.ops.leaves(writer.facts).single(),p.toPattern())
                val makeInput=bind(f,f.manager.zero,reader.facts,ret,global,relative)
                val makeInitial=makeGuide.initials(f.key,makeInput,bwPolicy).single()
                val makeBackward=run(f,makeInitial,make.asReversed().map { revEdge(it)!! },global,Direction.BACKWARD,relative)
                val makeSelected=makeGuide.intersect(f.key,makeInitial.initial,makeBackward.facts,bwPolicy).single()
                // The selected C5 rows are next-run guides, not a sticky layer lower bound.
                val nextWriter=guide(f,f.ops.leaves(makeSelected).single(),f.ops.leaves(writer.facts).single())
                    .initials(f.key,sourceActual,fwPolicy).single()
                val nextReader=guide(f,f.ops.leaves(takeSelected).single(),f.ops.leaves(reader.facts).single())
                    .initials(f.key,sinkActual,bwPolicy).single()
                assertEquals(writerSeed,nextWriter);assertEquals(readerSeed,nextReader)
                val results=listOf(writer,reader,takeForward,makeBackward)
                val normalCrossingRecords=results.count { it.facts.layer==Layer.NORMAL }
                val fingerprint=listOf(fact(f,writer.facts),fact(f,reader.facts),
                    "${takeInitial.initial.pathArray.size}:${takeInitial.initial.tail}:${takeInitial.layer}",
                    "${makeInitial.initial.pathArray.size}:${makeInitial.initial.tail}:${makeInitial.layer}",
                    fact(f,takeSelected),fact(f,makeSelected)).joinToString("|")
                println("RELATIVE_CAP global=$global relative=$relative writerCap=${writer.cap} readerCap=${reader.cap} middleForward=${fact(f,writer.facts)} middleBackward=${fact(f,reader.facts)} forwardMiddleInitial=${takeInitial.initial.pathArray.size}:${takeInitial.initial.tail}:${takeInitial.layer} backwardMiddleInitial=${makeInitial.initial.pathArray.size}:${makeInitial.initial.tail}:${makeInitial.layer} selectedSink=${fact(f,takeSelected)} selectedSource=${fact(f,makeSelected)} normalCrossingRecords=$normalCrossingRecords")
                if(relative) {
                    assertEquals(0,normalCrossingRecords)
                    assertEquals(Layer.DEMAND,takeSelected.layer)
                    assertEquals(Layer.DEMAND,makeSelected.layer)
                    assertEquals(1,takeInitial.initial.pathArray.size)
                    assertEquals(Tail.ANY,takeInitial.initial.tail)
                    assertEquals(1,makeInitial.initial.pathArray.size)
                    assertEquals(Tail.ANY,makeInitial.initial.tail)
                    if(oldRelativeFingerprint!=null)assertEquals(oldRelativeFingerprint,fingerprint)
                    oldRelativeFingerprint=fingerprint
                } else if(global>=2) {
                    assertEquals(4,normalCrossingRecords)
                    assertEquals(Layer.NORMAL,takeSelected.layer)
                    assertEquals(2,takeInitial.initial.pathArray.size)
                }
                if(global==3&&relative)println("RELATIVE_CAP_INLINE writer=${writer.steps} reader=${reader.steps} takeForward=${takeForward.steps} makeBackward=${makeBackward.steps}")
            }
        }
    }

    @Test fun `explicit deep ZERO source supplies the reader refinement that paired helpers cannot bootstrap`() {
        MethodAnalysisFixtures().use { f ->
            val t=MarkSlot.Concrete(f.mark("T"));val a=f.field("a");val b=f.field("b")
            val take=listOf(starEdge(arg,listOf(a),tmp,emptyList()),starEdge(tmp,listOf(b),ret,emptyList()))
            for(global in 2..7) {
                val source=f.fact(arg,listOf(a,b),mark=t)
                val actual=bounded(f,f.manager.zero,source,global,relative=true)
                assertEquals(global,cap(f.manager.zero,global,relative=true))
                assertEquals(Layer.NORMAL,actual.layer)
                val demand=guide(f,f.pattern(arg,listOf(a),Tail.ANY,t),f.pattern(ret,mark=t))
                val policy=RestrictedInitialPolicy(run=3,fieldLimit=global,direction=Direction.FORWARD,catalog=f.manager.marks)
                val initial=demand.initials(f.key,actual,policy).single()
                assertEquals(2,initial.initial.pathArray.size);assertEquals(Tail.EXACT,initial.initial.tail)
                val reader=run(f,initial,take,global,Direction.FORWARD,relative=true)
                val selected=demand.intersect(f.key,initial.initial,reader.facts,policy).single()
                assertEquals(Layer.NORMAL,selected.layer)
                println("ZERO_DEEP_SOURCE global=$global zeroCap=${cap(f.manager.zero,global,true)} readerInitialDepth=${initial.initial.pathArray.size} readerCap=${reader.cap} result=${fact(f,selected)}")
            }
        }
    }
}

